INSERT INTO tests (id, test_code, name, description, time_limit_seconds, status, created_at) VALUES (2, '02', 'Paper II — Listening & Reading', 'CEFR C1/C2 English Diagnostic Test, Paper II: 20 listening MCQs and 25 reading MCQs across varied genres. Question items are mapped to CEFR Levels C1 and C2 for candidates preparing for university programmes delivered in English.', 3600, 'draft', 1751860800000);
INSERT INTO test_parts (id, test_id, part_code, name, skill, sort_order) VALUES (3, 2, '01', 'Part A — Listening', 'listening', 1);
INSERT INTO test_parts (id, test_id, part_code, name, skill, sort_order) VALUES (4, 2, '02', 'Part B — Reading', 'reading', 2);
