INSERT INTO dimensions (id, test_part_id, dimension_code, key, name, short, sort_order) VALUES (14, 3, '02', 'listeningC1C2', 'Listening — C1/C2 Items', 'C1/C2', 2);
INSERT INTO dimensions (id, test_part_id, dimension_code, key, name, short, sort_order) VALUES (15, 4, '01', 'readingB2', 'Reading — B2 Items', 'B2', 1);
INSERT INTO dimensions (id, test_part_id, dimension_code, key, name, short, sort_order) VALUES (16, 4, '02', 'readingC1C2', 'Reading — C1/C2 Items', 'C1/C2', 2);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (1, 2, 'audio', 'Listening Q1 — Clear & structured announcement', '/api/assets/audio/test-02/20260701_01.mp3', 'Just a quick reminder about tomorrow’s company meeting. We’ll start at nine o’clock sharp in the main conference room on the fifth floor. First, the finance team will give a short update on this quarter’s results. Then we’ll talk about the new flexible‑working policy and answer any questions you might have. The whole meeting should last about an hour, and coffee will be available outside the room from half past eight.', '{"file":"20260701_01.mp3","genre":"Clear & structured announcement","skill":"Understanding the main idea and key details","audioKind":"an announcement"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (2, 2, 'audio', 'Listening Q2 — Steps/Instructions', '/api/assets/audio/test-02/20260701_02.mp3', 'If you’re having trouble logging into the new system, there are three things you should check before you call IT support. First, make sure you’re using your new password, not the old one. Second, confirm that you’ve typed your username without any extra spaces. Finally, if you still can’t get in, try restarting your computer. If none of that works, then send an email to the helpdesk with a screenshot of the error message.', '{"file":"20260701_02.mp3","genre":"Steps/Instructions","skill":"Understanding a sequence of steps and identifying conditions","audioKind":"a short talk"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (3, 2, 'audio', 'Listening Q3 — Short & coherent explanation', '/api/assets/audio/test-02/20260701_03.mp3', 'Many people think that learning a language is only about memorising vocabulary and grammar rules, but that view is quite limited. Of course, you need words and structures, but real progress often comes from regular contact with the language in meaningful situations—listening to podcasts, having short conversations, or reading things you actually enjoy. When you use the language for real purposes, you remember it more easily and feel more confident. So instead of waiting until your grammar is ‘perfect,’ it’s better to start using what you already know and build from there.', '{"file":"20260701_03.mp3","genre":"Short & coherent explanation","skill":"Grasping the main line of argument","audioKind":"a short talk"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (4, 2, 'audio', 'Listening Q4 — Evaluative language', '/api/assets/audio/test-02/20260701_04.mp3', 'To be honest, I was a bit disappointed with the training session this morning. The trainer seemed friendly enough, but most of what she said was just common sense. We spent almost an hour on ideas we already use every day, and there wasn’t much time left for questions at the end. I don’t think it was a complete waste of time, but I was hoping for something a little more practical.', '{"file":"20260701_04.mp3","genre":"Evaluative language","skill":"Identifying a fairly clear attitude","audioKind":"a short talk"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (5, 2, 'audio', 'Listening Q5 — Short & information‑dense announcement', '/api/assets/audio/test-02/20260701_05.mp3', 'This weekend, the city centre will be closed to most traffic because of the annual marathon. Roads along the river and near the old town will be blocked from six in the morning until two in the afternoon on Sunday. Drivers are advised to use the ring road instead, and public transport will run more frequently than usual. Organisers are asking residents to plan their journeys in advance and to allow extra time if they need to cross the city.', '{"file":"20260701_05.mp3","genre":"Short & information‑dense announcement","skill":"Extracting key factual details (time and day)","audioKind":"a radio report"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (6, 2, 'audio', 'Listening Q6 — Explanation of preference with reason', '/api/assets/audio/test-02/20260701_06.mp3', 'I know you suggested going to that new Italian restaurant on Friday, and it does look nice. The problem is, it’s a bit far from the office, and I have to catch a train straight after dinner. If we go somewhere closer to the station, I won’t have to rush so much. Could we try that Italian place another time, maybe at the weekend, when I’m not in such a hurry?', '{"file":"20260701_06.mp3","genre":"Explanation of preference with reason","skill":"Understanding a simple explanation of preference and identifying the key reason","audioKind":"a short talk"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (7, 2, 'audio', 'Listening Q7 — A loosely structured speech', '/api/assets/audio/test-02/20260701_07.mp3', 'When cities promote “greening,” they typically showcase the most visible changes: new parks, tree‑lined streets, stylish riverfronts. These look impressive in reports and campaign materials, but far less attention is paid to who actually benefits over time.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (8, 2, 'audio', 'Listening Q8 — A loosely structured speech', '/api/assets/audio/test-02/20260701_08.mp3', 'Debates about remote work often present a simple choice: either it dramatically boosts productivity or it inevitably damages it. This makes for strong headlines, but it hides how complex real working conditions are.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (9, 2, 'audio', 'Listening Q9 — Conversation — apology', '/api/assets/audio/test-02/20260701_09.mp3', 'Hey, sorry for the last‑minute text, but I’m totally snowed under at work today. I was meant to meet you at six, but there’s no way I’ll get out of here on time. If it’s all the same to you, can we push it back an hour? Worst case, we could just grab a quick bite near the station instead of doing the full dinner. I don’t want to keep you hanging around if you’ve got other plans, though, so just say if that’s a hassle and we’ll figure something out.', '{"file":"20260701_09.mp3","genre":"Conversation — apology","skill":"Guessing the meaning of idiomatic expressions from context","audioKind":"a short talk"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (10, 2, 'audio', 'Listening Q10 — Conversational remarks — indirect criticism', '/api/assets/audio/test-02/20260701_10.mp3', 'Look, I get that Mark’s under pressure, but the way he handled that meeting was really out of line. He just talked over people, shot down ideas without even listening, and then acted like he’d done us a favour by ‘keeping things on track.’ To be honest, it rubbed a lot of us the wrong way. We’re all pulling our weight, and then he swoops in at the last minute and takes all the credit. If that’s his idea of leadership, he’s got another thing coming.', '{"file":"20260701_10.mp3","genre":"Conversational remarks — indirect criticism","skill":"Inferring attitudes","audioKind":"a short talk"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (11, 2, 'audio', 'Listening Q11 — Conversation — conditional nature of agreeing', '/api/assets/audio/test-02/20260701_11.mp3', 'I’ve been thinking about that weekend trip you mentioned. I’d love a break, but money’s a bit tight at the moment, and those fancy hotels you sent over are way out of my league. I don’t want to rain on your parade, but if we’re going to make this work, we’ll have to dial it back a notch—maybe a cheaper place outside the city centre, or even a hostel. If that’s not your cup of tea, no worries, we can always save the trip for later when I’m not counting every penny.', '{"file":"20260701_11.mp3","genre":"Conversation — conditional nature of agreeing","skill":"Understanding idiomatic expressions and identifying the conditional nature of agreement","audioKind":"a short talk"}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (12, 2, 'audio', 'Listening Q12 — Short talk with shift from formal to informal register', '/api/assets/audio/test-02/20260701_12.mp3', 'As many of you know, our department has been under increasing pressure to demonstrate so‑called ‘impact’ beyond academic publications. Officially, the new framework is meant to encourage collaboration with communities and industry partners. On paper, that sounds perfectly reasonable.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (13, 2, 'audio', 'Listening Q13 — Short talk with shift from formal to informal register', '/api/assets/audio/test-02/20260701_13.mp3', 'Publicly, the company has been very clear: sustainability is, quote, ‘at the heart of everything we do.’ The press releases are full of ambitious targets and carefully crafted phrases about ‘reimagining our relationship with the planet.’ If you only read those statements, you might think we’re on the brink of a green revolution.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (14, 2, 'audio', 'Listening Q14 — Conversation — irony & humor', '/api/assets/audio/test-02/20260701_14.mp3', 'A (woman’s voice): “So, how did the big rollout go this morning?”
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (15, 2, 'audio', 'Listening Q15 — Conversation — self-deprecating humor', '/api/assets/audio/test-02/20260701_15.mp3', 'Lecturer: “When I first started teaching this course, I was convinced that if I just spoke more slowly and made my slides prettier, everyone would instantly grasp conditional probability.”
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (16, 2, 'audio', 'Listening Q16 — Moderated panel discussion', '/api/assets/audio/test-02/20260701_16.mp3', 'Moderator: “We’ve heard a lot about individual responsibility—recycling, shorter showers, buying ‘green’ products. Do these choices really make a difference?”
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (17, 2, 'audio', 'Listening Q17 — Conversation — identifying attitudes', '/api/assets/audio/test-02/20260701_17.mp3', 'Colleague A: “So, how did the committee respond to your proposal?”
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (18, 2, 'audio', 'Listening Q18 — Supervisor commenting on report quality', '/api/assets/audio/test-02/20260701_18.mp3', 'Thank you all for your hard work on this report. The layout is attractive, the graphs are clear, and the overall message is certainly timely. I can see that a great deal of effort has gone into meeting the deadline.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (19, 2, 'audio', 'Listening Q19 — Public register to private tone', '/api/assets/audio/test-02/20260701_19.mp3', 'When the client was in the room, Marco was the picture of professionalism: very calm, very polished, reassuring them that ‘a slight delay is perfectly normal in a project of this scale.’ He kept his tone light, even joked about how ‘these things never go exactly to plan,’ and they seemed satisfied enough.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (20, 2, 'audio', 'Listening Q20 — Criticism', '/api/assets/audio/test-02/20260701_20.mp3', 'I read your draft last night. It’s… impressive how much ground you’ve tried to cover in a single paper. The introduction sounds very confident, and you certainly don’t hold back on the big claims.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (21, 2, 'text', 'Narrative excerpt — “After the Dance”', NULL, 'Eliza was on her way home from the dance. Past the gas lights which were being extinguished by the gas lighter. Up High St where cable trams waited for the cable to start up in the morning. She knew this street very well. Every Saturday night she went to the dance, met her friends and her beau Arthur, and always came home by midnight. Her feet would barely touch the footpath. But tonight when Eliza looked at her watch, she saw it was one o’clock. Her steps became heavier. She had dallied with Arthur too long after the dance; it had felt like just a moment. She thought about the trouble she would be in.', '{"genre":"Narrative Writing","attribution":"An excerpt taken from “After the Dance” by Ashley MacGregor with the courtesy of Smashwords.com","skills":{"Q21":"Identifying the significance of part of the text","Q22":"Identifying underlying meaning"}}', 1751860800000);
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (22, 2, 'text', 'Notice — Entrepreneurial thought leaders seminar', NULL, 'In this seminar, entrepreneurial leaders share lessons from real-world experiences across various entrepreneurial settings. Speakers include entrepreneurs, leaders from global technology companies, venture capitalists, and best-selling authors. A half-hour fireside chat is followed by a half-hour question-and-answer session. Those seeking credit are required to complete post-event questions online.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (23, 2, 'text', 'Promotional page — LabelPro: Request Quote and Samples', NULL, 'LabelPro
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (24, 2, 'text', 'Open business letter — Macrosoft shareholder letter', NULL, 'TO OUR SHAREHOLDERS, CUSTOMERS, PARTNERS AND EMPLOYEES:
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (25, 2, 'text', 'Expository passage — Sustainable forestry and certification', NULL, 'Sustainable forestry is a balance of maintaining ecological integrity, meeting the landowner’s needs and desires and providing societal benefits. When the ecological integrity of a forest is maintained, the natural processes that occur within that forest are protected. Natural hydrology is maintained, forest soils are protected and a habitat for plants and animals flourishes.
INSERT INTO shared_resources (id, test_id, resource_type, title, content_url, text_content, metadata, created_at) VALUES (26, 2, 'text', 'Expository passage — The Creative Commons licenses', NULL, 'The Creative Commons copyright licenses and tools forge a balance inside the traditional “all rights reserved” setting that copyright law creates. Our tools give everyone from individual creators to large companies and institutions a simple, standardized way to grant copyright permissions to their creative work. The combination of our tools and our users is a vast and growing digital commons, a pool of content that can be copied, distributed, edited, remixed, and built upon, all within the boundaries of copyright law.
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (101, 2, 3, 13, 1, '001', 1, NULL, 1, 1);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (101, 101, '02-01-01-001-01', '01', 'What is the main purpose of the announcement?', 'To explain why the company’s results are worse than expected', 'To invite staff to an informal social event after work', 'To remind staff about the time and content of a meeting', 'To tell staff that the flexible‑working policy has been cancelled', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (102, 2, 3, 13, 2, '002', 2, NULL, 1, 2);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (102, 102, '02-01-01-002-01', '01', 'What should you do before emailing the helpdesk?', 'Use your old password and clear your browser history', 'Try three different usernames and then call IT support', 'Check password and username, then restart the computer', 'Restart the computer immediately without checking anything', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (103, 2, 3, 13, 3, '003', 3, NULL, 1, 3);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (103, 103, '02-01-01-003-01', '01', 'What is the speaker’s main point?', 'Students should avoid grammar until they are fluent', 'Real use of the language is essential for progress', 'Memorising vocabulary is the only way to learn', 'Reading is more useful than listening or speaking', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (104, 2, 3, 13, 4, '004', 4, NULL, 1, 4);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (104, 104, '02-01-01-004-01', '01', 'How does the speaker feel about the training session?', 'Very enthusiastic and impressed', 'Completely angry and offended', 'Slightly disappointed but not entirely negative', 'Uninterested and unaware of what happened', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (105, 2, 3, 13, 5, '005', 5, NULL, 1, 5);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (105, 105, '02-01-01-005-01', '01', 'Which statement is correct according to the report?', 'The city centre will be closed all weekend', 'Roads will be blocked on Sunday morning and early afternoon', 'Public transport will stop running during the marathon', 'Drivers must avoid the ring road on Sunday', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (106, 2, 3, 13, 6, '006', 6, NULL, 1, 6);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (106, 106, '02-01-01-006-01', '01', 'Why does the speaker prefer a different restaurant on Friday?', 'They don’t like Italian food.', 'They need to be near the station for their train.', 'They think the new restaurant is too expensive.', 'They are not free on Friday evening.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (107, 2, 3, 14, 7, '007', 7, NULL, 1, 7);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (107, 107, '02-01-02-007-01', '01', 'What is the speaker’s main point about the Riverside green corridor project?', 'It failed because residents did not support environmental improvements.', 'It succeeded environmentally but had unintended social consequences.', 'It shows that urban greening always increases quality of life for everyone.', 'It proves that economic development is more important than green spaces.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (108, 2, 3, 14, 8, '008', 8, NULL, 1, 8);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (108, 108, '02-01-02-008-01', '01', 'What does the speaker imply about claims that remote work is generally “good” or “bad” for productivity?', 'They are unreliable because they ignore how productivity is defined and managed.', 'They are accurate as long as employees work fixed hours from home.', 'They show that remote work is only suitable for highly autonomous workers.', 'They prove that most organizations function better with traditional office routines.', 'A', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (109, 2, 3, 14, 9, '009', 9, NULL, 1, 9);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (109, 109, '02-01-02-009-01', '01', 'What is the speaker mainly doing?', 'Cancelling the meeting because they will be out of town', 'Apologising for being late and suggesting a change of plan', 'Asking the listener to come to their office instead', 'Confirming that the original time and place still work', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (110, 2, 3, 14, 10, '010', 10, NULL, 1, 10);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (110, 110, '02-01-02-010-01', '01', 'What is the speaker’s attitude towards Mark?', 'Respectful but slightly intimidated', 'Neutral and mainly curious about his behaviour', 'Strongly critical of the way he behaves', 'Grateful for his effort under pressure', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (111, 2, 3, 14, 11, '011', 11, NULL, 1, 11);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (111, 111, '02-01-02-011-01', '01', 'What does the speaker mainly want the listener to understand?', 'They are not interested in going on the trip at all', 'They can only go if the plans are made less expensive', 'They would prefer to travel alone rather than with the listener', 'They insist on staying in the city centre to save time', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (112, 2, 3, 14, 12, '012', 12, NULL, 1, 12);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (112, 112, '02-01-02-012-01', '01', 'What is the speaker’s attitude towards the new “impact” framework?', 'Fully supportive and confident it will improve research quality', 'Mildly sceptical but generally willing to accept it as necessary', 'Critical of how it is implemented and described in official language', 'Indifferent, since it does not affect their work in any significant way', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (113, 2, 3, 14, 13, '013', 13, NULL, 1, 13);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (113, 113, '02-01-02-013-01', '01', 'What is implied about the company’s approach to sustainability?', 'It is mainly sincere, but poorly communicated to the public.', 'It is driven primarily by concern for investor profits, not the environment.', 'It balances image and substance equally in both public and private settings.', 'It places more emphasis on appearance than on fully committed action.', 'D', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (114, 2, 3, 14, 14, '014', 14, NULL, 1, 14);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (114, 114, '02-01-02-014-01', '01', 'What is the male speaker’s attitude towards the rollout?', 'Genuinely impressed by how smoothly everything went', 'Lightly humorous but clearly critical of how it was handled', 'Neutral and mainly focused on explaining technical details', 'Angry and demanding that the IT team be replaced', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (115, 2, 3, 14, 15, '015', 15, NULL, 1, 15);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (115, 115, '02-01-02-015-01', '01', 'What is the main purpose of the lecturer’s humorous remarks?', 'To suggest that conditional probability is impossible to teach', 'To blame students for not paying enough attention in class', 'To encourage students to ask questions when they are confused', 'To entertain the audience so they will like the lecturer more', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (116, 2, 3, 14, 16, '016', 16, NULL, 1, 16);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (116, 116, '02-01-02-016-01', '01', 'What is the speaker mainly trying to get the audience to do?', 'Focus only on changing their private habits', 'Stop worrying about their individual environmental impact', 'Question narratives that place all responsibility on individuals', 'Trust governments and companies to lead climate action', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (117, 2, 3, 14, 17, '017', 17, NULL, 1, 17);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (117, 117, '02-01-02-017-01', '01', 'What can be inferred from the committee’s response?', 'The proposal has been fully approved without any changes.', 'The proposal has been rejected outright and cannot proceed.', 'The proposal is likely to be accepted quickly with minimal revision.', 'The proposal faces delays and will need to be significantly revised.', 'D', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (118, 2, 3, 14, 18, '018', 18, NULL, 1, 18);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (118, 118, '02-01-02-018-01', '01', 'How does the speaker’s stance change over the course of the talk?', 'From doubtful at first to fully enthusiastic by the end.', 'From politely appreciative to more directly critical and cautious.', 'From neutral description to outright rejection with no positives.', 'From informal and friendly to distant and highly formal.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (119, 2, 3, 14, 19, '019', 19, NULL, 1, 19);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (119, 119, '02-01-02-019-01', '01', 'What do the changes in Marco’s tone and style suggest?', 'He is secretly pleased that the project is delayed.', 'He feels more comfortable being honest once the client has left.', 'He is equally relaxed and positive in both situations.', 'He is mainly angry with the client for demanding too much.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (120, 2, 3, 14, 20, '020', 20, NULL, 1, 20);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (120, 120, '02-01-02-020-01', '01', 'What is the speaker really doing in this feedback?', 'Insulting the writer’s style without offering any help', 'Genuinely praising the draft and encouraging stronger claims', 'Using cautious praise to introduce concerns about tone and positioning', 'Avoiding any comment on tone or interpersonal effect', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (121, 2, 4, 15, 21, '021', 21, NULL, 1, 21);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (121, 121, '02-02-01-021-01', '01', 'Which statement best captures the significance of the description of the street and time?', 'It contrasts Eliza’s usual carefree routine with her growing anxiety.', 'It shows that Eliza is unfamiliar with the neighbourhood.', 'It emphasises that Eliza is obsessed with dancing.', 'It suggests that Arthur lives far from Eliza’s home.', 'A', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (122, 2, 4, 15, 21, '022', 22, NULL, 1, 22);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (122, 122, '02-02-01-022-01', '01', 'The sentence ‘her steps became heavier’ in line 6 most strongly suggests that Eliza', 'has begun to worry about the consequences of being late.', 'is physically exhausted after dancing.', 'cannot remember the way home.', 'regrets going to the dance at all.', 'A', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (123, 2, 4, 15, 22, '023', 23, NULL, 1, 23);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (123, 123, '02-02-01-023-01', '01', 'What is the primary purpose of this text?', 'To present the structure and key details of an entrepreneurial seminar.', 'To analyse how global technology has changed entrepreneurship.', 'To advertise books written by venture capitalists.', 'To compare different graduate programmes in management science.', 'A', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (124, 2, 4, 15, 22, '024', 24, NULL, 1, 24);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (124, 124, '02-02-01-024-01', '01', 'Which description best captures the central focus of the seminar?', 'Practical insights drawn from the experiences of entrepreneurial leaders.', 'Technical training in management science and engineering methods.', 'Detailed instruction on founding and running venture-capital funds.', 'Critical reviews of recent books on global technology.', 'A', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (125, 2, 4, 15, 22, '025', 25, NULL, 1, 25);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (125, 125, '02-02-01-025-01', '01', 'Which group is the seminar most clearly designed for, based on the text?', 'Individuals seeking informal inspiration, with no interest in formal study.', 'Graduate-level learners who may wish to combine online viewing with academic credit.', 'Corporate employees required to attend mandatory training sessions.', 'Undergraduate students looking for basic introductions to business vocabulary.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (126, 2, 4, 15, 23, '026', 26, NULL, 1, 26);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (126, 126, '02-02-01-026-01', '01', 'What is the key message of this LabelPro’s online text?', 'Customers can easily contact the company.', 'Customers can save time by using the company’s service.', 'Customers can get support on the design and delivery of their orders.', 'Customers can see the real objects free of charge before ordering them.', 'D', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (127, 2, 4, 15, 23, '027', 27, NULL, 1, 27);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (127, 127, '02-02-01-027-01', '01', 'What does a potential customer have to do if they want to get samples?', 'Request a quote from LabelPro', 'Ask LabelPro for physical samples for testing', 'Provide LabelPro with the information needed for making samples', 'Email, fax, or call LabelPro', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (128, 2, 4, 15, 24, '028', 28, NULL, 1, 28);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (128, 128, '02-02-01-028-01', '01', 'Which description best captures the main purpose of this letter?', 'To apologise to stakeholders for recent declines in revenue and profit.', 'To negotiate new contractual terms with partners and developers.', 'To reassure stakeholders about Macrosoft’s performance and future prospects.', 'To provide a technical explanation of Macrosoft’s financial reporting methods.', 'C', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (129, 2, 4, 15, 24, '029', 29, NULL, 1, 29);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (129, 129, '02-02-01-029-01', '01', 'What does the way financial information is presented mainly suggest about Macrosoft’s recent year?', 'It was both profitable and able to return significant value to shareholders.', 'It was marked by rising revenue but collapsing cash flow.', 'It focused entirely on cutting costs, with little investment in new products.', 'It involved heavy borrowing to fund shareholder dividends.', 'A', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (130, 2, 4, 15, 24, '030', 30, NULL, 1, 30);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (130, 130, '02-02-01-030-01', '01', 'Which statement best describes Bannerman’s attitude toward Macrosoft’s future?', 'He is cautiously optimistic, acknowledging both opportunities and serious risks.', 'He is strongly optimistic, emphasising opportunity and excitement more than potential difficulties.', 'He is doubtful, focusing on the hard work ahead and downplaying achievements.', 'He is neutral, limiting himself to factual reporting without evaluative language.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (131, 2, 4, 16, 25, '031', 31, NULL, 1, 31);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (131, 131, '02-02-02-031-01', '01', 'This passage is mainly about _____.', 'Sustainable forestry and its certification', 'Benefits of landowners of forests', 'Benefits of obtaining forest certification', 'Ecological integrity and environment conservation', 'A', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (132, 2, 4, 16, 25, '032', 32, NULL, 1, 32);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (132, 132, '02-02-02-032-01', '01', 'What does the passage suggest about the relationship between landowners’ goals and sustainable forest management?', 'Landowners’ economic goals always conflict with ecological integrity.', 'A variety of landowner goals can be accommodated within sustainable management.', 'Sustainable management is only possible when landowners focus on wildlife rather than timber.', 'Landowners must give up their own needs to achieve sustainability.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (133, 2, 4, 16, 25, '033', 33, NULL, 1, 33);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (133, 133, '02-02-02-033-01', '01', 'It can be inferred from the passage that if a landowner manages its forest in a sustainable way, then _____.', 'it is easier to produce certified wood.', 'plants, animals and even human beings can be benefited.', 'environmental, social and economic standards can be set.', 'certified wood does not have to be limited to a few species.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (134, 2, 4, 16, 25, '034', 34, NULL, 1, 34);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (134, 134, '02-02-02-034-01', '01', 'Which statement best reflects the passage’s view of forest certification systems?', 'They provide a single global standard that guarantees top-quality wood.', 'They offer principles and criteria for sustainability but differ in approach and may have practical limitations.', 'They mainly exist to protect landowners from economic risk.', 'They are unnecessary if landowners already practise sustainable forestry.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (135, 2, 4, 16, 25, '035', 35, NULL, 1, 35);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (135, 135, '02-02-02-035-01', '01', 'What can be inferred about the relationship between sustainable forestry and forest certification in this passage?', 'Certification and sustainability are identical concepts used interchangeably.', 'Certification is presented as one formal method of checking sustainability, but sustainability itself is defined more broadly.', 'Certification is described as irrelevant compared to ecological integrity.', 'Certification is portrayed as the main cause of environmental degradation.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (136, 2, 4, 16, 25, '036', 36, NULL, 1, 36);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (136, 136, '02-02-02-036-01', '01', 'It is implied in the passage that _____.', 'Forest certification systems have no standards.', 'Certified wood is not necessarily of higher quality or grade than non-certified wood.', 'To keep a forest sustainable, landowners should acquire forest certification.', 'Sustainable forest management is in conflict with the interests of the landowners.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (137, 2, 4, 16, 25, '037', 37, NULL, 1, 37);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (137, 137, '02-02-02-037-01', '01', 'Which of the following best captures a tension implied in the passage?', 'Sustainable forestry benefits landowners but harms downstream communities.', 'Forest certification promotes sustainability yet may limit species choice and not guarantee higher veneer quality.', 'Ecological integrity requires ignoring landowners’ needs.', 'Societal benefits are incompatible with protecting plants and animals.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (138, 2, 4, 16, 26, '038', 38, NULL, 1, 38);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (138, 138, '02-02-02-038-01', '01', 'Paragraph 1 (lines 1–7) is mainly about ______.', 'copyright licenses and law', 'how to combine the tools, the users, and the pool of content', 'encouraging people to grant copyright permissions to others', 'the purpose of having the Creative Commons copyright licenses and tools', 'D', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (139, 2, 4, 16, 26, '039', 39, NULL, 1, 39);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (139, 139, '02-02-02-039-01', '01', 'According to paragraph 3, when Creative Commons licensors choose their licenses, they should consider _____.', 'how they require people to use their work', 'whom they allow to distribute their work', 'what types of derivative works are allowed', 'whether they allow people to use their work for commercial use and edit their work', 'D', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (140, 2, 4, 16, 26, '040', 40, NULL, 1, 40);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (140, 140, '02-02-02-040-01', '01', 'According to paragraphs 5, 6 and 7, which of the following statements is true?', 'The “three-layer” design ensures the user-friendliness of the licenses.', 'The first layer of the “three-layer” design makes the licenses ‘human readable’.', 'The second layer of the “three-layer” design aims to comply with legal code.', 'The final layer of the “three-layer” design facilitates the work of software developers.', 'D', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (141, 2, 4, 16, 26, '041', 41, NULL, 1, 41);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (141, 141, '02-02-02-041-01', '01', 'Which of the following would be a suitable title for the article?', 'The “Three-layer” Design of the Creative Commons', 'The Creative Commons: Uses & Design', 'Effective Uses of Creative Commons', 'Licenses for the New Century', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (142, 2, 4, 16, 26, '042', 42, NULL, 1, 42);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (142, 142, '02-02-02-042-01', '01', 'How does paragraph 1 position Creative Commons within traditional copyright?', 'As a complete replacement for copyright law.', 'As a way to balance “all rights reserved” with more flexible permission‑sharing.', 'As a system that forces creators to give up control of their work.', 'As a tool designed only for large institutions, not individual creators.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (143, 2, 4, 16, 26, '043', 43, NULL, 1, 43);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (143, 143, '02-02-02-043-01', '01', 'What is the main advantage of the “three-layer” design for different kinds of users?', 'It lets lawyers, ordinary users, and software systems all interpret the same license in a form suited to their needs.', 'It removes the need for legal code, replacing it with human‑readable summaries.', 'It prevents non‑lawyers from understanding the full terms of the licenses.', 'It limits Creative Commons licenses to projects using advanced search engines.', 'A', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (144, 2, 4, 16, 26, '044', 44, NULL, 1, 44);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (144, 144, '02-02-02-044-01', '01', 'Why does the passage describe “ShareAlike” as helping the digital commons grow over time?', 'It forces all derivative works to be sold commercially, increasing revenue.', 'It requires derivative works to be made available under the same license terms, expanding the pool of reusable content.', 'It restricts reuse to the original licensor, protecting the commons from change.', 'It encourages users to keep their new works private, avoiding legal problems.', 'B', NULL, 1751860800000);
INSERT INTO question_groups (id, test_id, test_part_id, dimension_id, shared_resource_id, group_code, canonical_number, legacy_qid, variant_count, sort_order) VALUES (145, 2, 4, 16, 26, '045', 45, NULL, 1, 45);
INSERT INTO questions (id, question_group_id, question_code, variant_code, prompt_text, option_a, option_b, option_c, option_d, correct_answer, explanation, created_at) VALUES (145, 145, '02-02-02-045-01', '01', 'What does paragraph 8 mainly suggest about the importance of the machine‑readable layer of Creative Commons licenses?', 'Without it, creators would be unable to retain copyright on their works.', 'It makes it practically possible for users and platforms to discover and aggregate open content at scale.', 'It ensures that only large platforms like Wikimedia can use Creative Commons licenses.', 'It is primarily aimed at replacing human judgement with automated copyright enforcement.', 'B', NULL, 1751860800000);
